using System.Text.Json;
using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"), Description("Returns application configuration data")]
    public static string GetSettings()
    {
        var config = new
        {
            Environment = "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { DarkMode = true, BetaAccess = false }
        };
        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Gets the value of a configuration key")]
    public static string GetConfigValue(
        [Description("The configuration key to look up")] string key)
    {
        var settings = new Dictionary<string, string>
        {
            ["environment"] = "Production",
            ["max_retries"] = "3",
            ["timeout_seconds"] = "30"
        };

        return settings.TryGetValue(key.ToLowerInvariant(), out var value)
            ? value
            : $"Key '{key}' not found. Available keys: {string.Join(", ", settings.Keys)}";
    }

    [McpServerTool, Description("Updates a configuration value (in-memory only)")]
    public static string UpdateConfigValue(
        [Description("The configuration key to update")] string key,
        [Description("The new value to set")] string value)
    {
        return $"Configuration '{key}' updated to '{value}' (in-memory).";
    }
}

